def rotate_90(grid):
    """Rotate 90° clockwise: (r, c) -> (c, rows-1-r)"""
    rows = len(grid)
    cols = len(grid[0])
    return [[grid[rows-1-r][c] for r in range(rows)] for c in range(cols)]

def rotate_180(grid):
    """Rotate 180° = rotate 90 twice"""
    return rotate_90(rotate_90(grid))

def rotate_270(grid):
    """Rotate 270° = rotate 90 three times (or counter-clockwise once)"""
    return rotate_90(rotate_90(rotate_90(grid)))

